const originalTexts = new WeakMap();
const shellLabels = {
    en: { 'Fale conosco': 'Contact us', 'Planejar interpretação': 'Plan interpreting', 'Enviar documento para avaliação': 'Submit document for assessment', 'Solicitar orçamento': 'Request a quote' },
    es: { 'Fale conosco': 'Contáctenos', 'Planejar interpretação': 'Planificar la interpretación', 'Enviar documento para avaliação': 'Enviar documento para evaluación', 'Solicitar orçamento': 'Solicitar presupuesto' },
    zh: { 'Fale conosco': '联系我们', 'Planejar interpretação': '规划口译', 'Enviar documento para avaliação': '提交文件进行评估', 'Solicitar orçamento': '获取报价' }
};
function translateText(lang) {
    const dictionary = translations[lang] || translations.pt;
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach(node => {
        if (!originalTexts.has(node)) originalTexts.set(node, node.nodeValue);
        const original = originalTexts.get(node);
        const trimmed = original.trim();
        if (!trimmed || node.parentElement.closest('script, style, .lab-code, .lab-clock')) return;
        const translated = dictionary[trimmed] || shellLabels[lang]?.[trimmed];
        if (translated) node.nodeValue = original.replace(trimmed, translated);
    });
    const attributes = ['placeholder', 'aria-label', 'alt', 'title'];
    document.querySelectorAll('*').forEach(element => attributes.forEach(attribute => {
        const key = `original${attribute.replace('-', '')}`;
        if (!element.dataset[key] && element.hasAttribute(attribute)) element.dataset[key] = element.getAttribute(attribute);
        const original = element.dataset[key];
        if (original && dictionary[original]) element.setAttribute(attribute, dictionary[original]);
    }));
    document.documentElement.lang = lang === 'zh' ? 'zh-CN' : lang;
    document.querySelectorAll('.lang-btn').forEach(button => button.classList.toggle('active', button.dataset.lang === lang));
    const floatingLabel = document.querySelector('.floating-language span');
    if (floatingLabel) floatingLabel.textContent = lang === 'zh' ? '中' : lang.toUpperCase();
    localStorage.setItem('desktrad-lang', lang);
    const titles = { pt: 'Desktrad Traduções | Precisão que conecta', en: 'Desktrad Translations | Precision that connects', es: 'Desktrad Traducciones | Precisión que conecta', zh: 'Desktrad 翻译 | 精准连接世界' };
    document.title = titles[lang];
}
function changeLanguage(lang) { translateText(lang); }
function initializeTranslations() {
    document.querySelectorAll('.lang-btn').forEach(button => button.addEventListener('click', () => translateText(button.dataset.lang)));
    document.querySelectorAll('.lang-link').forEach(link => link.addEventListener('click', event => { event.preventDefault(); translateText(link.dataset.lang); }));
    window.addEventListener('desktrad:language', event => translateText(event.detail));
    translateText(localStorage.getItem('desktrad-lang') || 'pt');
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initializeTranslations);
else initializeTranslations();